<?php require_once __DIR__.'/../app/db.php'; require_once __DIR__.'/../app/layout.php'; require_login(); require_perm('contrats'); $pdo=pdo(); $rows=$pdo->query("SELECT r.*, CONCAT(c.nom,' ',c.prenom) client, CONCAT(v.marque,' ',v.modele,' - ',v.immatriculation) voiture FROM reservations r JOIN clients c ON c.id=r.client_id JOIN voitures v ON v.id=r.voiture_id ORDER BY r.id DESC")->fetchAll(); render_header('Contrats de location'); ?>
<section class="panel"><div class="panel-head"><h2>Contrats prêts à imprimer</h2><a class="btn primary" href="/reservations.php?action=new">+ Nouveau contrat</a></div><div class="table-wrap"><table><thead><tr><th>Référence</th><th>Client</th><th>Véhicule</th><th>Période</th><th>2ᵉ conducteur</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['reference'])?></b></td><td><?=e($r['client'])?></td><td><?=e($r['voiture'])?></td><td><?=e($r['date_debut'])?> → <?=e($r['date_fin'])?></td><td><?= $r['avec_conducteur2']?'Oui':'Non' ?></td><td><a class="btn small" target="_blank" href="/contrat.php?id=<?=$r['id']?>">Voir / imprimer</a></td></tr><?php endforeach;?></tbody></table></div></section><?php render_footer(); ?>
